var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();
app.Run();

// You don't interact with the CLR directly, but it provides features like this:

// 1. Automatic Memory Management (GC)
var list = new List<int>(); // The CLR allocates and eventually cleans this up.

// 2. Exception Handling
try { 
    int x = 1 / 0; 
} catch (DivideByZeroException) { 
    // The CLR caught the crash safely! 
}

// C# Code
public int Add(int a, int b) { return a + b; }

// ↓ (Compile Time - Roslyn) ↓

// MSIL (Stored in DLL)
// IL_0000: ldarg.1
// IL_0001: ldarg.2
// IL_0002: add
// IL_0003: ret

// ↓ (Runtime - JIT) ↓

// Machine Code (01010011 11010101)

// ✅ MANAGED CODE: The GC cleans this up automatically
string name = "Bob"; 

// ❌ UNMANAGED CODE: Calling a raw C++ Windows API
// The GC CANNOT clean this up. You must call it carefully.
[DllImport("user32.dll")]
public static extern int MessageBox(IntPtr hWnd, String text, String caption, int options);

// You can inspect the Assembly Manifest using Reflection:
using System.Reflection;

// Get the currently running Assembly (The DLL)
Assembly myAssembly = Assembly.GetExecutingAssembly();

// Read the Manifest to get the version number
Console.WriteLine(myAssembly.GetName().Version);

string data = "123,456,789";

// ❌ BAD: Allocates 2 brand new strings on the Heap!
string part1 = data.Substring(0, 3);
string part2 = data.Substring(4, 3);

// ✅ GOLD STANDARD: ZERO Heap Allocations.
ReadOnlySpan<char> spanData = data.AsSpan();
ReadOnlySpan<char> span1 = spanData.Slice(0, 3);
ReadOnlySpan<char> span2 = spanData.Slice(4, 3);
